package cloud.ohiofiles.app

import android.util.Base64
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import cloud.ohiofiles.app.data.crypto.ChatCrypto
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import java.math.BigInteger
import java.security.AlgorithmParameters
import java.security.KeyFactory
import java.security.KeyPair
import java.security.spec.*

/** Vector generated by executing the repository's actual WebCrypto chat-crypto.ts. */
@RunWith(AndroidJUnit4::class)
class ChatCryptoInteropTest {
    private val expected = "OhioFiles — Android 💚\nUnicode: zażółć"
    private val payload = Json.parseToJsonElement("""{"version":1,"ciphertext":"2QYWRs5FSTXr8lCBcs96-Sx5sDRcjN0Jf9tPJeCCXY92ODrkdbs4QrsbT9zA43WC4yocLgR0xeRSs9nVP_M","iv":"ICEiIyQlJicoKSor","context":"AAECAwQFBgcICQoLDA0ODxAR","ephemeralPublicKey":"BHzyexiNA09-ilI4AwS1GsPAiWnid_IbNaYLSPxHZpl4B3dVENuO0EApPZrGn3Qw27p9reY86YIpngS3nSJ4c9E","envelope":{"wrappedKey":"3-PYb7vH6nO1f9mucPrTT08NN8v0XryuYFDHk-IBgG47lSUt7o7v2MTWeP8wDGjl","iv":"QEFCQ0RFRkdISUpL"}}""").jsonObject
    private fun decode(value: String) = Base64.decode(value, Base64.URL_SAFE or Base64.NO_WRAP or Base64.NO_PADDING)
    private fun identity(): ChatCrypto.Identity {
        val raw = decode("BGsX0fLhLEJH-Lzm5WOkQPJ3A32BLeszoPShOUXYmMKWT-NC4v4af5uO5-tKfA-eFivOM1drMV7Oy7ZAaDe_UfU")
        val parameters = AlgorithmParameters.getInstance("EC").apply { init(ECGenParameterSpec("secp256r1")) }.getParameterSpec(ECParameterSpec::class.java)
        val factory = KeyFactory.getInstance("EC")
        val publicKey = factory.generatePublic(ECPublicKeySpec(ECPoint(BigInteger(1, raw.copyOfRange(1, 33)), BigInteger(1, raw.copyOfRange(33, 65))), parameters))
        val privateKey = factory.generatePrivate(PKCS8EncodedKeySpec(decode("MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAGhRANCAARrF9Hy4SxCR_i85uVjpEDydwN9gS3rM6D0oTlF2JjClk_jQuL-Gn-bjufrSnwPnhYrzjNXazFezsu2QGg3v1H1")))
        return ChatCrypto.Identity("recipient-test", "device-test-123", KeyPair(publicKey, privateKey))
    }
    @Test fun decryptsWebCryptoUnicodePayload() {
        assertEquals(expected, ChatCrypto.decrypt(payload, identity(), "sender-test", "recipient-test"))
    }
    @Test fun rejectsChangedSenderAndCiphertext() {
        assertTrue(runCatching { ChatCrypto.decrypt(payload, identity(), "other-sender", "recipient-test") }.isFailure)
        val changed = JsonObject(payload + ("iv" to JsonPrimitive("MCEiIyQlJicoKSor")))
        assertTrue(runCatching { ChatCrypto.decrypt(changed, identity(), "sender-test", "recipient-test") }.isFailure)
        val missingEnvelope = JsonObject(payload + ("envelope" to JsonNull))
        assertTrue(runCatching { ChatCrypto.decrypt(missingEnvelope, identity(), "sender-test", "recipient-test") }.isFailure)
    }
    @Test fun nativeEncryptRoundTripAndAtRestIdentityPersistence() {
        val context = InstrumentationRegistry.getInstrumentation().targetContext
        val first = ChatCrypto.identity(context, "https://interop.test", "test-identity", "test-device-123")
        val second = ChatCrypto.identity(context, "https://interop.test", "test-identity", "test-device-123")
        assertEquals(first.publicKey, second.publicKey)
        val encrypted = ChatCrypto.encrypt(expected, "sender-test", first.sessionId, listOf(ChatCrypto.Target(first.sessionId, first.deviceId, first.publicKey)))
        val readable = JsonObject(encrypted + ("envelope" to encrypted["envelopes"]!!.jsonArray.single()))
        assertEquals(expected, ChatCrypto.decrypt(readable, second, "sender-test", first.sessionId))
    }
}
